def _extract_buffers(self) -> Dict[int, Buffer]:
buffers = {}
for node in self.nodes.values():
if node.op == "ALLOC":
buffers[node.buf_id] = Buffer(
id=node.buf_id,
size=node.size,
type=node.type,
alloc_node_id=node.id
)
for node in self.nodes.values():
if node.op == "FREE" and node.buf_id in buffers:
buffers[node.buf_id].free_node_id = node.id
elif node.bufs:
for buf_id in node.bufs:
if buf_id in buffers:
buffers[buf_id].users.append(node.id)
